-- Migration 028: regions for the 2019 all-India boundary set
-- Regions the 2019 boundary set (states, districts and subdistricts; Bhuvan/SOI
-- via saketlab/bharatviz and datta07/INDIAN-SHAPEFILES) needs that the regions
-- table doesn't have. IDs are the set's own <type>_<code> ids. Names are the
-- set's names in title case ("TANGI-CHOUDWAR" -> "Tangi-Choudwar"), with a
-- trailing '*' source marker removed from 7 of them ("JAKHOLI*" -> "Jakholi");
-- they are not checked against LGD. Parents are the set's parentID, except Mahe and Yanam,
-- whose parent state_34 is ut_34 here. None of them existed when this was
-- written; the insert fails (unique region_id) if one already does, so the
-- rollback only ever removes rows this migration added.

BEGIN;

